sections.syntax:
CREATE TABLE nom_table (
  colonne1 type_données [contrainte],
  colonne2 type_données [contrainte],
  ...
);

examples.code:
CREATE TABLE Students (
  id        INT,
  name      VARCHAR(100),
  age       INT,
  email     VARCHAR(150)
);

CREATE TABLE Employees (
  emp_id    INT           PRIMARY KEY,
  full_name VARCHAR(100)  NOT NULL,
  salary    DECIMAL(10,2) NOT NULL,
  hire_date DATE
);

CREATE TABLE Products (
  product_id   INT          PRIMARY KEY,
  product_name VARCHAR(200) NOT NULL,
  price        DECIMAL(8,2) DEFAULT 0.00,
  sku          VARCHAR(50)  UNIQUE
);

CREATE TABLE Orders (
  order_id    INT PRIMARY KEY,
  customer_id INT NOT NULL,
  order_date  DATE,
  FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

CREATE TABLE Accounts (
  account_id INT           PRIMARY KEY,
  username   VARCHAR(50)   NOT NULL UNIQUE,
  age        INT           CHECK (age >= 18),
  balance    DECIMAL(12,2) CHECK (balance >= 0)
);

sections.syntax:
DROP TABLE nom_table;

-- Version sécurisée (pas d'erreur si la table n'existe pas) :
DROP TABLE IF EXISTS nom_table;

examples.code:
ALTER TABLE Employees
DROP COLUMN middle_name,
DROP COLUMN fax_number;

sections.syntax:
-- MySQL 8.0+ :
ALTER TABLE nom_table
RENAME COLUMN ancien_nom TO nouveau_nom;

-- MySQL ancien / SQL Server :
ALTER TABLE nom_table
CHANGE ancien_nom nouveau_nom type_données;

-- MySQL :
RENAME TABLE ancien_nom TO nouveau_nom;

-- SQL Server :
EXEC sp_rename 'ancien_nom', 'nouveau_nom';

-- Colonne unique :
CREATE TABLE nom_table (
  col INT PRIMARY KEY,
  ...
);

-- Clé composite :
CREATE TABLE nom_table (
  col1 INT,
  col2 INT,
  PRIMARY KEY (col1, col2)
);

-- Ajouter à une table existante :
ALTER TABLE nom_table ADD PRIMARY KEY (nom_colonne);

examples.code:
CREATE TABLE Customers (
  customer_id INT PRIMARY KEY,
  name        VARCHAR(100) NOT NULL
);

CREATE TABLE Enrollments (
  student_id  INT,
  course_id   INT,
  enrolled_on DATE,
  PRIMARY KEY (student_id, course_id)
);

CREATE TABLE Customers (
  customer_id INT PRIMARY KEY,
  name        VARCHAR(100)
);

CREATE TABLE Orders (
  order_id    INT PRIMARY KEY,
  customer_id INT,
  total       DECIMAL(10,2),
  FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

CREATE TABLE Users (
  user_id  INT          PRIMARY KEY,
  email    VARCHAR(150) UNIQUE,
  username VARCHAR(50)  UNIQUE
);

CREATE TABLE Employees (
  emp_id  INT           PRIMARY KEY,
  name    VARCHAR(100)  NOT NULL,
  age     INT           CHECK (age >= 18 AND age <= 65),
  salary  DECIMAL(10,2) CHECK (salary > 0)
);

CREATE TABLE Orders (
  order_id INT PRIMARY KEY,
  status   VARCHAR(20) CHECK (status IN ('pending', 'shipped', 'delivered', 'cancelled'))
);

CREATE TABLE Products (
  product_id INT PRIMARY KEY,
  price      DECIMAL(8,2),
  discount   DECIMAL(5,2),
  CONSTRAINT chk_discount CHECK (discount < price)
);
